"use client";

import { useState, useRef, useCallback } from "react";

const SCRAMBLE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#[]_*/Ôûæ%?ÔûôÔûÆÔêåÔëá┬º┬▒";

const WA_LINK = "https://wa.me/573223737487?text=Hola,%20quiero%20adquirir%20entradas%20para%20CROMO";

/* ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
   Generic scramble hook
ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */
function useScramble(text: string, frames = 14) {
    const [display, setDisplay] = useState(text);
    const rafRef = useRef<number | undefined>(undefined);

    const scramble = useCallback(() => {
        cancelAnimationFrame(rafRef.current!);
        let frame = 0;
        const step = () => {
            frame++;
            setDisplay(
                text.split("").map((char) => {
                    // preserve special chars & accented letters in their positions
                    if (" []├í├®├¡├│├║├╝├▒".includes(char)) return char;
                    if (frame > frames - 2) return char;
                    return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
                }).join("")
            );
            if (frame < frames) {
                rafRef.current = requestAnimationFrame(step);
            } else {
                setDisplay(text);
            }
        };
        step();
    }, [text, frames]);

    return { display, scramble };
}

